<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\UserConsentPurposesUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserConsentPurposesUserAccessor
{
    private UserConsentPurposesUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserConsentPurposesUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserConsentPurposesUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserConsentPurposesUserVO::from($user);
        return $copy;
    }
}
